import test from 'node:test';
import assert from 'node:assert/strict';
import { parseCount } from './parse.mjs';

test('valid count', () => assert.equal(parseCount('3'), 3));

test('SPEC PARSE-1 accepts only entire safe ASCII decimal digit strings', () => {
  for (const [input, expected] of [['0', 0], ['03', 3], ['3', 3]]) {
    assert.equal(parseCount(input), expected);
  }

  for (const input of ['3x', '', ' 3', '-1', '1.5', null, '9007199254740992']) {
    assert.throws(() => parseCount(input), new TypeError('invalid count'));
  }
});

export function parseCount(value) {
  if (typeof value !== 'string' || !/^[0-9]+$/.test(value)) {
    throw new TypeError('invalid count');
  }

  const count = Number(value);
  if (!Number.isSafeInteger(count)) {
    throw new TypeError('invalid count');
  }

  return count;
}
